
using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StoreMaster.Server.Data; using StoreMaster.Server.Models; using StoreMaster.Server.Services; using System.Text.Json; using BCrypt.Net;
namespace StoreMaster.Server.Controllers;
[ApiController][Authorize][Route("api/v1/users")] public class UsersController:ControllerBase{readonly StoreMasterDbContext db; readonly PermissionService p; public UsersController(StoreMasterDbContext db,PermissionService p){this.db=db;this.p=p;} int Sid()=>int.Parse(User.FindFirst("storeId")?.Value??"0"); int Uid()=>int.Parse(User.FindFirst("sub")?.Value??"0"); StoreUser? Me()=>db.StoreUsers.FirstOrDefault(x=>x.StoreId==Sid()&&x.UserId==Uid()&&x.Active);
[HttpGet] public async Task<IActionResult> All(){var me=Me(); if(me==null||!p.Can(me,"users.manage"))return Forbid(); var raw=await (from su in db.StoreUsers join u in db.Users on su.UserId equals u.Id where su.StoreId==Sid() select new{id=u.Id,name=u.Name,phone=u.Phone,role=su.Role,permissionsJson=su.PermissionsJson,active=su.Active}).ToListAsync(); var items=raw.Select(x=>new{id=x.id,name=x.name,phone=x.phone,role=x.role,permissions=JsonSerializer.Deserialize<List<string>>(x.permissionsJson) ?? new List<string>(),active=x.active}).ToList(); return Ok(new{items});}
[HttpPost] public async Task<IActionResult> Create(UserDto x){var me=Me(); if(me==null||!p.Can(me,"users.manage"))return Forbid(); var lic=await db.Licenses.Where(z=>z.StoreId==Sid()&&z.Status=="ACTIVE").OrderByDescending(z=>z.ExpiresAt).FirstOrDefaultAsync(); if(lic!=null){var count=await db.StoreUsers.CountAsync(z=>z.StoreId==Sid()&&z.Active); if(count>=lic.MaxUsers)return BadRequest(new{message="سقف کاربران این لایسنس تکمیل شده است"});} var username=string.IsNullOrWhiteSpace(x.Username) ? $"user-{Guid.NewGuid():N}"[..13] : x.Username.Trim(); var u=new User{Username=username,Name=x.Name,Phone=x.Phone,PinHash=BCrypt.Net.BCrypt.HashPassword(x.Pin)}; db.Users.Add(u); await db.SaveChangesAsync(); db.StoreUsers.Add(new StoreUser{StoreId=Sid(),UserId=u.Id,Role=x.Role,PermissionsJson=JsonSerializer.Serialize(x.Permissions ?? new List<string>())}); await db.SaveChangesAsync(); return Ok(new{id=u.Id});}
[HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,UserDto x){var me=Me(); if(me==null||!p.Can(me,"users.manage"))return Forbid(); var su=await db.StoreUsers.FirstOrDefaultAsync(z=>z.StoreId==Sid()&&z.UserId==id); var u=await db.Users.FindAsync(id); if(su==null||u==null)return NotFound(); u.Name=x.Name;u.Phone=x.Phone;if(!string.IsNullOrWhiteSpace(x.Pin))u.PinHash=BCrypt.Net.BCrypt.HashPassword(x.Pin);su.Role=x.Role;su.PermissionsJson=JsonSerializer.Serialize(x.Permissions??new());su.Active=x.Active;await db.SaveChangesAsync();return Ok(new{success=true});}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var me=Me();if(me==null||!p.Can(me,"users.manage"))return Forbid();var su=await db.StoreUsers.FirstOrDefaultAsync(z=>z.StoreId==Sid()&&z.UserId==id);if(su==null)return NotFound();if(id==Uid())return BadRequest(new{message="حساب جاری قابل حذف نیست"});su.Active=false;await db.SaveChangesAsync();return Ok(new{success=true});}}
public record UserDto(string Name,string Phone,string Role,string? Pin,bool Active,List<string>? Permissions,string? Username = null);
